  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Ensure no IAM policies documents allow '*' as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows '*' as a resource for 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances', which could potentially grant excessive permissions."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies does not allow write access without constraints",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows 'sagemaker:CreatePresignedNotebookInstanceUrl' on all resources without constraints, potentially allowing unauthorized access."
    }
  ],
  "patched_code": ```hcl
resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl"
        ]
        Resource = "arn:aws:sagemaker:*:*:notebook-instance/*"
      },
    ]
  })
}
```,
  "fix_summary": "Restricted 'sagemaker:CreatePresignedNotebookInstanceUrl' to notebook instances and kept 'sagemaker:ListNotebookInstances' on '*', as it is a list operation that cannot be restricted to specific resources."
}
